def sort(a):
    """标准冒泡:每趟把当前未排定区间的最大元素『浮』到右端,共 n-1 趟。
    内层上界 n-1-i 随趟数收缩,因为末尾 i 个元素已就位。"""
    a = list(a)
    n = len(a)
    for i in range(n - 1):
        for j in range(n - 1 - i):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
    return a

def sort(a):
    """带 swapped 标志:每趟开始置 False,发生交换则置 True;
    若整趟没有任何交换,说明数组已有序,立即 break。
    对已排序/近乎有序输入只需一趟扫描,最好 O(n)。"""
    a = list(a)
    n = len(a)
    for i in range(n - 1):
        swapped = False
        for j in range(n - 1 - i):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
                swapped = True
        if not swapped:
            break
    return a
